// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;

    bytes4 constant IERC165_ID = 0x01ffc9a7;
    bytes4 constant IACCESSCONTROL_ID = 0x7965db0b;

    function setUp() public { c = new Size(); }

    function testFuzz_property(uint256 seed) public {
        // The fuzzer chooses both the arbitrary raw id and which of the two
        // supported ids is exercised (fuzzed parity of `seed`).
        bytes4 id;
        if (seed % 2 == 0) {
            id = IERC165_ID;
        } else if (seed % 4 == 1) {
            id = IACCESSCONTROL_ID;
        } else {
            id = bytes4(uint32(uint256(keccak256(abi.encode(seed)))));
        }

        // General rule: c supports exactly the IERC165 and IAccessControl
        // interface ids, and no other id.
        bool supported;
        try c.supportsInterface(id) returns (bool r) {
            supported = r;
        } catch {
            supported = false;
        }

        assertTrue(supported == (id == IERC165_ID || id == IACCESSCONTROL_ID));
    }
}
